import dev.zomboid.hordes.PathThrottle;import dev.zomboid.hordes.fast.FastReflection;
public class Checks {static int n;static void check(boolean b){if(!b)throw new AssertionError(n);n++;}public static class Level{public long time;public long getGameTime(){return time;}}public static class Mob{Level l;Mob(Level l){this.l=l;}public Level level(){return l;}}public static class Nav{public int calls;public boolean done,success=true;public boolean isDone(){return done;}public boolean moveTo(double x,double y,double z,double speed){calls++;return success;}}public static class Parent{private int field=3;public String which(String v){return "parent";}}public static class Child extends Parent{public String which(String v){return "child";}public String which(Integer v){return "integer";}public static int twice(int x){return x*2;}public String fail(){throw new IllegalArgumentException("expected");}}
public static void main(String[]args){Level l=new Level();Mob m=new Mob(l);Nav nav=new Nav();Object[] target={1d,2d,3d,1d};PathThrottle.call(nav,"moveTo",target,m);check(nav.calls==1);nav.done=true;for(int i=1;i<20;i++){l.time=i;PathThrottle.call(nav,"moveTo",target,m);}check(nav.calls==1);l.time=20;PathThrottle.call(nav,"moveTo",target,m);check(nav.calls==2);nav.done=false;l.time=40;PathThrottle.call(nav,"moveTo",target,m);check(nav.calls==2);Object[] moved={50d,2d,3d,1d};PathThrottle.call(nav,"moveTo",moved,m);check(nav.calls==3);l.time=41;PathThrottle.call(nav,"moveTo",target,m);check(nav.calls==3);Nav bad=new Nav();bad.success=false;l.time=100;PathThrottle.call(bad,"moveTo",target,m);l.time=120;PathThrottle.call(bad,"moveTo",moved,m);check(bad.calls==1);l.time=140;PathThrottle.call(bad,"moveTo",moved,m);check(bad.calls==2);l.time=200;int count=0;for(int i=0;i<20;i++){Nav v=new Nav();PathThrottle.call(v,"moveTo",target,m);count+=v.calls;}check(count==4);l.time=1;PathThrottle.call(nav,"moveTo",target,m);check(nav.calls==4);Child c=new Child();check(FastReflection.call(c,"which","x").equals("child"));check(FastReflection.call(c,"which",3).equals("integer"));check(FastReflection.call(Child.class,"twice",4).equals(8));check(FastReflection.get(c,"field").equals(3));FastReflection.set(c,"field",8);check(FastReflection.get(c,"field").equals(8));check(FastReflection.type("Checks$Child")==Child.class);boolean throwsCause=false;try{FastReflection.call(c,"fail");}catch(IllegalStateException e){throwsCause=e.getCause() instanceof IllegalArgumentException;}check(throwsCause);System.out.println("Path budget and reflection checks: "+n);}}
